/* ============================ Đi dạo: chọn và trộn đoạn chuyển động của nhân vật có xương (thuần) ============================
   Từ dáng (pose) và tốc độ mặt bằng (m/s) tính trọng số năm đoạn idle / walk / jog / sprint / photo và hệ số tua `rate` cho đoạn di chuyển.
   Thuần: không import three, không đụng DOM, không cấp phát (gọi mỗi khung cho từng nhân vật, D-018): kết quả ghi vào `out` do bên gọi giữ.
   - Di chuyển (pose 1, 2 và 3 khi còn tốc độ ngang): trộn theo tốc độ, walk (≤ walkTo) → jog (jogAt) → sprint (≥ sprintFrom), tuyến tính giữa các mốc; dáng đi / chạy chỉ cho biết đang di chuyển.
   - rate = tốc độ thật / tốc độ tự nhiên của đoạn trộn, kẹp [rateMin, rateMax]: chân chạm đất gần đúng không trượt.
   - Dáng lạ (khách bản cũ, số ngoài 0..4, NaN) và rơi không còn tốc độ ngang: đứng yên (idle). Khách bản cũ gửi dáng 3 khi nhảy; người đó hiện đứng yên. */
import { CONFIG } from '../../config';
import { ST_POSE_WALK, ST_POSE_RUN, ST_POSE_FALL, ST_POSE_PHOTO } from './motion';

export const ST_CLIPS = ['idle', 'walk', 'jog', 'sprint', 'photo'] as const;
export type StClip = typeof ST_CLIPS[number];

export interface StClipMix {
  w: Float32Array;   // 5 trọng số theo thứ tự ST_CLIPS, tổng = 1
  rate: number;      // hệ số tua đoạn di chuyển
  loco: boolean;     // đang di chuyển (walk / jog / sprint có trọng số)
}

const A = CONFIG.stroll.anim;

export function stClipMix(pose: number, speed: number, natural: ArrayLike<number>, out: StClipMix): void {
  const w = out.w, v = speed > 0 ? speed : 0;
  w[0] = 0; w[1] = 0; w[2] = 0; w[3] = 0; w[4] = 0;
  out.rate = 1; out.loco = false;
  if (pose === ST_POSE_PHOTO) { w[4] = 1; return; }
  const move = pose === ST_POSE_WALK || pose === ST_POSE_RUN || (pose === ST_POSE_FALL && v >= A.fallMin);
  if (!move) { w[0] = 1; return; }
  out.loco = true;
  if (v <= A.walkTo) w[1] = 1;
  else if (v < A.jogAt) { const t = (v - A.walkTo) / (A.jogAt - A.walkTo); w[1] = 1 - t; w[2] = t; }
  else if (v < A.sprintFrom) { const t = (v - A.jogAt) / (A.sprintFrom - A.jogAt); w[2] = 1 - t; w[3] = t; }
  else w[3] = 1;
  const nat = w[1] * natural[1] + w[2] * natural[2] + w[3] * natural[3];
  const r = nat > 1e-6 ? v / nat : 1;
  out.rate = r < A.rateMin ? A.rateMin : r > A.rateMax ? A.rateMax : r;
}

/* Mô hình của slot: mình luôn mô hình 0; người khác dùng 1..others theo slot (slot âm vẫn trong khoảng) */
export function stModelFor(slot: number, isSelf: boolean): number {
  if (isSelf) return 0;
  const n = A.others;
  return 1 + (((slot % n) + n) % n);
}
/* ===== Dù lượn, đi dạo và lái xe nhiều người: máy trạng thái phiên (không DOM, không three) =====
   Một phiên thuộc một loại (kind): 'fly' giành chỗ bay, 'walk' giành chỗ đi dạo, 'drive' giành chỗ lái xe. Ba nhóm 5 slot riêng; peers là nhóm cùng loại với mình
   (dùng cho đầy chỗ, chọn người xem, lời mời). Phase 'flying' nghĩa là "đang giữ chỗ" cho mọi loại (đi dạo, lái xe cũng vậy). */
import type { Flyer, Kind, ServerMsg } from './protocol';
import type { Transport } from './client';
import { multiParams } from './params';

export type Phase = 'connecting' | 'lobby' | 'flying' | 'watching' | 'solo';
export type Notice = '' | 'offline' | 'lost' | 'late' | 'nameBad' | 'released';

export class MultiSession {
  phase: Phase = 'connecting';
  flyers: Flyer[] = [];
  walkers: Flyer[] = [];   // người đi dạo (lobby.walkers); máy chủ cũ không gửi
  drivers: Flyer[] = [];   // người lái xe (lobby.drivers); máy chủ cũ không gửi
  mySlot = -1;
  watched = -1;       // slot đang xem (trong nhóm cùng loại), -1 = không ai
  invite = false;     // đang xem và còn chỗ trống
  notice: Notice = '';
  name = '';
  onChange: () => void = () => {};
  onPos: (f: number[][]) => void = () => {};
  onWalkPos: (w: number[][]) => void = () => {};
  peersDrive: (d: number[][]) => void = () => {};   // nhóm d của gói pos (mẫu onWalkPos): mỗi phần tử [slot, x, y, z, yaw, v, st, giờ gửi]
  private t: Transport | null = null;
  private disposed = false;
  private first = true; // chưa nhận lobby nào

  constructor(private connect: () => Promise<Transport>, private pick: (n: number) => number = n => Math.floor(Math.random() * n), readonly kind: Kind = 'fly') {}

  /* Danh sách cùng loại với mình */
  get peers(): Flyer[] { return this.kind === 'walk' ? this.walkers : this.kind === 'drive' ? this.drivers : this.flyers; }

  /* Số chỗ của nhóm cùng loại */
  private get cap(): number { return this.kind === 'walk' ? multiParams.stroll.slots : this.kind === 'drive' ? multiParams.drive.slots : multiParams.slots; }

  open(): void {
    this.connect().then(t => {
      if (this.disposed) { t.close(); return; }
      this.t = t;
      t.onMessage = m => this.recv(m);
      t.onClose = () => this.lost();
    }, () => {
      if (this.disposed) return;
      this.phase = 'solo'; this.notice = 'offline'; this.onChange();
    });
  }

  /* Người lái chỉ xin chỗ sau khi lobby đầu đã có drivers: máy chủ cũ (main trước D-034) coi join kind 'drive' là join bay và cho chiếm một chỗ bay */
  join(name: string): void {
    this.name = name; this.notice = '';
    if (this.kind === 'drive' && this.first) return;
    this.t?.send(this.kind === 'fly' ? { t: 'join', name } : { t: 'join', name, kind: this.kind });
  }

  // Rời chỗ (do rời máy): trả slot, chuyển sang xem, báo 'released' như khi máy chủ thu hồi chỗ
  leave(): void {
    if (this.phase !== 'flying') return;
    this.t?.send({ t: 'leave' });
    this.notice = 'released'; this.toWatching();
    this.onChange();
  }

  // ts: giờ gửi (ms, đồng hồ của khách này) để người xem đặt mẫu theo trục giờ người gửi
  sendPos(x: number, y: number, z: number, yaw: number, bank: number, ts: number): void {
    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, bank, ts });
  }

  // Người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 rơi (bản cũ: nhảy), 4 chụp ảnh) thay cho bank
  sendWalk(x: number, y: number, z: number, yaw: number, pose: number, ts: number): void {
    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, pose, ts });
  }

  // Người lái: v tốc độ có dấu (m/s), st góc lái (rad) thay cho bank / pose; ts giờ gửi (ms, đồng hồ khách này), không truyền thì lấy performance.now()
  sendDrive(p: { x: number; y: number; z: number; yaw: number; v: number; st: number; ts?: number }): void {
    if (this.phase !== 'flying') return;
    const ts = typeof p.ts === 'number' ? p.ts : Math.round(performance.now());
    this.t?.send({ t: 'pos', x: p.x, y: p.y, z: p.z, yaw: p.yaw, v: p.v, st: p.st, ts });
  }

  heartbeat(): void {
    if (this.phase === 'flying') this.t?.send({ t: 'hb' });
  }

  dispose(): void {
    this.disposed = true;
    this.t?.close(); this.t = null;
  }

  private toWatching(): void {
    this.phase = 'watching'; this.mySlot = -1;
    if (this.kind === 'walk') this.walkers = this.walkers.filter(f => f.slot !== this.mySlotWas);
    else if (this.kind === 'drive') this.drivers = this.drivers.filter(f => f.slot !== this.mySlotWas);
    else this.flyers = this.flyers.filter(f => f.slot !== this.mySlotWas);
    this.fixWatched();
  }
  private mySlotWas = -1;

  // Giữ watched nếu người đó còn; không thì chọn ngẫu nhiên người khác (cùng loại)
  private fixWatched(): void {
    const ids = this.peers.map(f => f.slot);
    if (this.phase === 'watching') {
      if (!ids.includes(this.watched)) this.watched = ids.length ? ids[this.pick(ids.length)] : -1;
      this.invite = ids.length < this.cap;
    } else { this.watched = -1; this.invite = false; }
  }

  private lost(): void {
    if (this.disposed) return;
    this.phase = 'solo'; this.notice = 'lost';
    this.flyers = []; this.walkers = []; this.drivers = []; this.mySlot = -1; this.watched = -1; this.invite = false;
    this.t = null; this.onChange();
  }

  /* Máy chủ cũ (lobby đầu không có walkers / drivers) không biết chỗ đi dạo / lái xe: đóng kết nối, đi / lái một mình như khi không kết nối được */
  private offline(): void {
    const t = this.t;
    this.t = null;
    if (t) { t.onClose = () => {}; t.onMessage = () => {}; t.close(); }
    this.phase = 'solo'; this.notice = 'offline';
    this.flyers = []; this.walkers = []; this.drivers = [];
    this.onChange();
  }

  private recv(m: ServerMsg): void {
    if (this.disposed) return;
    switch (m.t) {
      case 'lobby':
        if (this.first && this.kind === 'walk' && !Array.isArray(m.walkers)) { this.first = false; this.offline(); return; }
        if (this.first && this.kind === 'drive' && !Array.isArray(m.drivers)) { this.first = false; this.offline(); return; }
        this.flyers = m.flyers;
        this.walkers = Array.isArray(m.walkers) ? m.walkers : [];
        this.drivers = Array.isArray(m.drivers) ? m.drivers : [];
        if (this.first) {
          this.first = false;
          if (this.peers.length >= this.cap) this.phase = 'watching';
          else this.phase = 'lobby';
        }
        // đang giữ chỗ: danh sách chỉ để hiển thị
        this.fixWatched();
        break;
      case 'joined':
        this.phase = 'flying'; this.mySlot = m.slot; this.mySlotWas = m.slot; this.notice = '';
        this.fixWatched();
        break;
      case 'rejected':
        if (m.why === 'name') this.notice = 'nameBad';
        else {
          this.notice = 'late';   // giành trước khi đang xem, hoặc ngay ở sảnh (chỗ cuối vừa có người lúc bấm): đều báo lý do
          this.phase = 'watching';
          this.fixWatched();
        }
        break;
      case 'pos':
        this.onPos(m.f);
        if (Array.isArray(m.w)) this.onWalkPos(m.w);
        if (Array.isArray(m.d)) this.peersDrive(m.d);
        return;
      case 'released':
        if (this.phase === 'flying') { this.notice = 'released'; this.toWatching(); }
        break;
    }
    this.onChange();
  }
}
/* ===== Dù lượn, đi dạo và lái xe nhiều người: bước chọn slot và nhập tên (trong hộp thoại #chooser) =====
   Hiện sau khi bấm thẻ Dù lượn (hoặc Đi dạo) lúc có máy chủ: 5 chấm + "Còn N trên 5 chỗ", tên những người cùng loại (session.peers), ô tên, nút Bay ngay / Đi dạo ngay / Lái ngay.
   Chữ chọn theo session.kind (multi/keys.ts: exMp* cho dù lượn, st* cho đi dạo, dr* cho lái xe); tên nhớ dùng chung cho ba loại.
   Cập nhật trực tiếp theo MultiSession; tên người khác chỉ ghi bằng textContent. Tên của mình nhớ ở localStorage.
   Pha lobby: cho nhập tên và giành chỗ. Pha solo (không kết nối được): báo ngoại tuyến. Nút Bay một mình hiện ở cả hai pha (đóng phiên rồi bay một mình).
   Pha flying: gọi onFly. Pha watching (hết chỗ): gọi onWatch (chế độ xem do Task 7 làm).
   Nút Quay lại hoặc Esc: đóng phiên (đóng WebSocket), trả lại các thẻ, tiêu đề và aria-labelledby, gọi onBack để chọn lại.
   Trình nghe gắn một lần cho cả trang và đọc sảnh đang mở (cur), nên vào sảnh nhiều lần không nhân đôi. */
import { CONFIG } from '../../config';
import { t, onChange as onLang } from '../../i18n';
import { exMulti } from './index';
import { exSanitizeName } from './protocol';
import { exMpKeys, exMpSlots } from './keys';
import type { MultiSession } from './session';

export interface LobbyCallbacks { onFly: () => void; onWatch: () => void; onSolo: () => void; onBack: () => void }

const M = CONFIG.explore.multi;
const NAME_KEY = 'exMpName';
const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;

export function loadName(): string { try { return localStorage.getItem(NAME_KEY) || ''; } catch { return ''; } }
export function saveName(n: string): void { try { localStorage.setItem(NAME_KEY, n); } catch { /* bộ nhớ trình duyệt bị chặn */ } }

let listKey = '';
let bound = false;
let cur: { session: MultiSession; cb: LobbyCallbacks } | null = null;   // sảnh đang mở; null = đã đóng (vào bay, xem, bay một mình, quay lại)

/* Đóng sảnh rồi gọi f (một lần) */
function finish(f: () => void): void {
  if (!cur) return;
  cur = null; exMulti.onChange = () => {};
  f();
}

/* Trả hộp thoại về các thẻ: hiện tiêu đề, gắn lại aria-labelledby */
function restoreCards(): void {
  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement;
  root.hidden = true;
  box.querySelector<HTMLElement>('.ex-cards')!.hidden = false;
  $('exTitle').hidden = false;
  box.setAttribute('aria-labelledby', 'exTitle');
}

/* Quay lại / Esc: đóng phiên và về các thẻ */
function back(): void {
  const c = cur; if (!c) return;
  finish(() => { exMulti.end(); restoreCards(); c.cb.onBack(); });
}

/* Bay một mình (có hay không có máy chủ): đóng phiên để không gửi/nhận gì */
function solo(): void {
  const c = cur; if (!c) return;
  finish(() => { exMulti.end(); c.cb.onSolo(); });
}

/* Ghi chữ theo khóa và nhớ khóa ở data-i18n (đổi ngôn ngữ thì i18n dịch lại đúng khóa của loại sảnh đang mở) */
function setKey(id: string, key: string): void {
  const el = $(id);
  if (el.dataset.i18n !== key) el.dataset.i18n = key;
  const v = t(key);
  if (el.textContent !== v) el.textContent = v;
}

function render(): void {
  if (!cur) return;
  const session = cur.session, cb = cur.cb, K = exMpKeys(session.kind);
  const fly = $<HTMLButtonElement>('exMpFly'), soloBtn = $<HTMLButtonElement>('exMpSolo'), input = $<HTMLInputElement>('exMpNameIn');
  const ph = session.phase;
  if (ph === 'flying') { finish(cb.onFly); return; }
  if (ph === 'watching') { finish(cb.onWatch); return; }
  /* Chữ theo loại sảnh: bầu trời (dù lượn) hoặc sông Hàn (đi dạo, lái xe) */
  setKey('exMpSky', K.sky);
  setKey('exMpFly', K.go);
  setKey('exMpSolo', K.solo);
  setKey('exMpOffline', K.offline);
  const offline = ph === 'solo';
  $('exMpOnline').hidden = offline;
  $('exMpOffline').hidden = !offline;
  soloBtn.classList.toggle('ex-mp-alt', !offline);   // có máy chủ: nút phụ; ngoại tuyến: nút chính
  if (offline) { if (document.activeElement !== soloBtn) soloBtn.focus({ preventScroll: true }); return; }
  const ready = ph === 'lobby';
  const peers = session.peers;
  const free = exMpSlots(session.kind) - peers.length;
  $('exMpSeats').textContent = !ready ? '…' : K.full && free <= 0 ? t(K.full) : t(K.seats, { n: free });
  $('exMpNameHint').textContent = t('exMpNameMax', { n: M.nameMax });
  const taken = new Set(peers.map(f => f.slot));
  $('exMpDots').querySelectorAll<HTMLElement>('i').forEach((d, i) => {
    d.classList.toggle('on', taken.has(i));
    d.style.background = taken.has(i) ? M.colors[i % M.colors.length] : '';
  });
  const key = session.kind + '#' + peers.map(f => f.slot + ':' + f.name).join('|');
  if (key !== listKey) {
    listKey = key;
    const list = $('exMpList'); list.textContent = '';
    for (const f of peers) {
      const row = document.createElement('div'); row.className = 'ex-mp-row';
      const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
      const nm = document.createElement('span'); nm.textContent = f.name; nm.dir = 'auto';
      row.append(dot, nm); list.appendChild(row);
    }
  }
  $('exMpNameBad').hidden = session.notice !== 'nameBad';
  fly.disabled = !ready || exSanitizeName(input.value) === null;
}

function go(): void {
  if (!cur) return;
  const name = exSanitizeName($<HTMLInputElement>('exMpNameIn').value);
  if (name === null || cur.session.phase !== 'lobby') return;
  saveName(name);
  cur.session.join(name);
}

/* Gắn trình nghe một lần */
function bind(): void {
  if (bound) return;
  bound = true;
  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement, input = $<HTMLInputElement>('exMpNameIn');
  input.addEventListener('input', () => {
    if (!cur) return;
    $('exMpNameBad').hidden = true;
    const ok = exSanitizeName(input.value);
    if (ok !== null) saveName(ok);   // nhớ ngay khi hợp lệ, tải lại trang vẫn còn
    $<HTMLButtonElement>('exMpFly').disabled = cur.session.phase !== 'lobby' || ok === null;
  });
  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); go(); } });
  $('exMpFly').addEventListener('click', go);
  $('exMpSolo').addEventListener('click', solo);
  $('exMpBack').addEventListener('click', back);
  box.addEventListener('keydown', (e) => { if (e.key === 'Escape' && cur) { e.preventDefault(); back(); } });
  onLang(() => render());
}

/* Hiện bước riêng thay cho các thẻ và gắn nó vào phiên; trả ngay (phiên đang ở pha 'connecting') */
