/* ===== Dù lượn, đi dạo và lái xe nhiều người: bước chọn slot và nhập tên (trong hộp thoại #chooser) =====
   Hiện sau khi bấm thẻ Dù lượn (hoặc Đi dạo) lúc có máy chủ: 5 chấm + "Còn N trên 5 chỗ", tên những người cùng loại (session.peers), ô tên, nút Bay ngay / Đi dạo ngay / Lái ngay.
   Chữ chọn theo session.kind (multi/keys.ts: exMp* cho dù lượn, st* cho đi dạo, dr* cho lái xe); tên nhớ dùng chung cho ba loại.
   Cập nhật trực tiếp theo MultiSession; tên người khác chỉ ghi bằng textContent. Tên của mình nhớ ở localStorage.
   Pha lobby: cho nhập tên và giành chỗ. Pha solo (không kết nối được): báo ngoại tuyến. Nút Bay một mình hiện ở cả hai pha (đóng phiên rồi bay một mình).
   Pha flying: gọi onFly. Pha watching (hết chỗ): gọi onWatch (chế độ xem do Task 7 làm).
   Nút Quay lại hoặc Esc: đóng phiên (đóng WebSocket), trả lại các thẻ, tiêu đề và aria-labelledby, gọi onBack để chọn lại.
   Trình nghe gắn một lần cho cả trang và đọc sảnh đang mở (cur), nên vào sảnh nhiều lần không nhân đôi. */
import { CONFIG } from '../../config';
import { t, onChange as onLang } from '../../i18n';
import { exMulti } from './index';
import { exSanitizeName } from './protocol';
import { exMpKeys, exMpSlots } from './keys';
import type { MultiSession } from './session';

export interface LobbyCallbacks { onFly: () => void; onWatch: () => void; onSolo: () => void; onBack: () => void }

const M = CONFIG.explore.multi;
const NAME_KEY = 'exMpName';
const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;

export function loadName(): string { try { return localStorage.getItem(NAME_KEY) || ''; } catch { return ''; } }
export function saveName(n: string): void { try { localStorage.setItem(NAME_KEY, n); } catch { /* bộ nhớ trình duyệt bị chặn */ } }

let listKey = '';
let bound = false;
let cur: { session: MultiSession; cb: LobbyCallbacks } | null = null;   // sảnh đang mở; null = đã đóng (vào bay, xem, bay một mình, quay lại)

/* Đóng sảnh rồi gọi f (một lần) */
function finish(f: () => void): void {
  if (!cur) return;
  cur = null; exMulti.onChange = () => {};
  f();
}

/* Trả hộp thoại về các thẻ: hiện tiêu đề, gắn lại aria-labelledby */
function restoreCards(): void {
  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement;
  root.hidden = true;
  box.querySelector<HTMLElement>('.ex-cards')!.hidden = false;
  $('exTitle').hidden = false;
  box.setAttribute('aria-labelledby', 'exTitle');
}

/* Quay lại / Esc: đóng phiên và về các thẻ */
function back(): void {
  const c = cur; if (!c) return;
  finish(() => { exMulti.end(); restoreCards(); c.cb.onBack(); });
}

/* Bay một mình (có hay không có máy chủ): đóng phiên để không gửi/nhận gì */
function solo(): void {
  const c = cur; if (!c) return;
  finish(() => { exMulti.end(); c.cb.onSolo(); });
}

/* Ghi chữ theo khóa và nhớ khóa ở data-i18n (đổi ngôn ngữ thì i18n dịch lại đúng khóa của loại sảnh đang mở) */
function setKey(id: string, key: string): void {
  const el = $(id);
  if (el.dataset.i18n !== key) el.dataset.i18n = key;
  const v = t(key);
  if (el.textContent !== v) el.textContent = v;
}

function render(): void {
  if (!cur) return;
  const session = cur.session, cb = cur.cb, K = exMpKeys(session.kind);
  const fly = $<HTMLButtonElement>('exMpFly'), soloBtn = $<HTMLButtonElement>('exMpSolo'), input = $<HTMLInputElement>('exMpNameIn');
  const ph = session.phase;
  if (ph === 'flying') { finish(cb.onFly); return; }
  if (ph === 'watching') { finish(cb.onWatch); return; }
  /* Chữ theo loại sảnh: bầu trời (dù lượn) hoặc sông Hàn (đi dạo, lái xe) */
  setKey('exMpSky', K.sky);
  setKey('exMpFly', K.go);
  setKey('exMpSolo', K.solo);
  setKey('exMpOffline', K.offline);
  const offline = ph === 'solo';
  $('exMpOnline').hidden = offline;
  $('exMpOffline').hidden = !offline;
  soloBtn.classList.toggle('ex-mp-alt', !offline);   // có máy chủ: nút phụ; ngoại tuyến: nút chính
  if (offline) { if (document.activeElement !== soloBtn) soloBtn.focus({ preventScroll: true }); return; }
  const ready = ph === 'lobby';
  const peers = session.peers;
  const free = exMpSlots(session.kind) - peers.length;
  $('exMpSeats').textContent = !ready ? '…' : K.full && free <= 0 ? t(K.full) : t(K.seats, { n: free });
  $('exMpNameHint').textContent = t('exMpNameMax', { n: M.nameMax });
  const taken = new Set(peers.map(f => f.slot));
  $('exMpDots').querySelectorAll<HTMLElement>('i').forEach((d, i) => {
    d.classList.toggle('on', taken.has(i));
    d.style.background = taken.has(i) ? M.colors[i % M.colors.length] : '';
  });
  const key = session.kind + '#' + peers.map(f => f.slot + ':' + f.name).join('|');
  if (key !== listKey) {
    listKey = key;
    const list = $('exMpList'); list.textContent = '';
    for (const f of peers) {
      const row = document.createElement('div'); row.className = 'ex-mp-row';
      const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
      const nm = document.createElement('span'); nm.textContent = f.name; nm.dir = 'auto';
      row.append(dot, nm); list.appendChild(row);
    }
  }
  $('exMpNameBad').hidden = session.notice !== 'nameBad';
  fly.disabled = !ready || exSanitizeName(input.value) === null;
}

function go(): void {
  if (!cur) return;
  const name = exSanitizeName($<HTMLInputElement>('exMpNameIn').value);
  if (name === null || cur.session.phase !== 'lobby') return;
  saveName(name);
  cur.session.join(name);
}

/* Gắn trình nghe một lần */
function bind(): void {
  if (bound) return;
  bound = true;
  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement, input = $<HTMLInputElement>('exMpNameIn');
  input.addEventListener('input', () => {
    if (!cur) return;
    $('exMpNameBad').hidden = true;
    const ok = exSanitizeName(input.value);
    if (ok !== null) saveName(ok);   // nhớ ngay khi hợp lệ, tải lại trang vẫn còn
    $<HTMLButtonElement>('exMpFly').disabled = cur.session.phase !== 'lobby' || ok === null;
  });
  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); go(); } });
  $('exMpFly').addEventListener('click', go);
  $('exMpSolo').addEventListener('click', solo);
  $('exMpBack').addEventListener('click', back);
  box.addEventListener('keydown', (e) => { if (e.key === 'Escape' && cur) { e.preventDefault(); back(); } });
  onLang(() => render());
}

/* Hiện bước riêng thay cho các thẻ và gắn nó vào phiên; trả ngay (phiên đang ở pha 'connecting') */
export function exShowLobby(session: MultiSession, cb: LobbyCallbacks): void {
  bind();
  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement, input = $<HTMLInputElement>('exMpNameIn');
  box.querySelector<HTMLElement>('.ex-cards')!.hidden = true;
  $('exTitle').hidden = true; $('exMpLostNote').hidden = true;
  box.setAttribute('aria-labelledby', 'exMpSky');
  root.hidden = false;
  if (!input.value) input.value = loadName();
  listKey = '';
  cur = { session, cb };
  exMulti.onChange = render;
  render();
  input.focus({ preventScroll: true });
}
/* ===== Dù lượn, đi dạo và lái xe nhiều người: điều phối phía khách =====
   Nối MultiSession (kết nối, phiên) với exRemotes (dù người khác), stAvatars (người đi dạo khác), exDrivers (xe người khác), nhãn tên và danh sách người chơi.
   Cả ba loại thấy nhau; mỗi phiên chỉ giữ một loại chỗ (session.kind). drCars.group chỉ ở trong cảnh khi có xe (exDrivers.onCars), không thì 0 lệnh vẽ.
   Chỉ mở kết nối khi có người gọi begin(); ?test mà không có multi= thì url() rỗng nên không bao giờ mở WebSocket. */
import { scene, camera } from '../../core/renderer';
import { CONFIG } from '../../config';
import { t, onChange as onLang } from '../../i18n';
import { exConnect } from './client';
import { MultiSession } from './session';
import { exRemotes } from './remote';
import { exLabelsUpdate, exLabelsClear } from './labels';
import { ExIdle } from './idle';
import { stAvatars } from '../stroll/avatars';
import { exDrivers } from './remoteDrive';
import { drCars } from '../drive/cars';
import type { Kind } from './protocol';
import type { GliderState } from '../flight';
import type { StState } from '../stroll/motion';
import type { DrState } from '../drive/motion';

const M = CONFIG.explore.multi;
let session: MultiSession | null = null;
let sentAt = -1e9;
let rosterKey = '';
let idle: ExIdle | null = null;
let idleTimer = 0, beatTimer = 0;   // setInterval kiểm tra rời máy + nhịp sống; chỉ chạy khi đang bay
let idleShown = '';                 // chữ đang hiện ở #exMpIdle ('' = ẩn): chỉ ghi DOM khi đổi

/* ===== Rời máy: đếm bằng setInterval (tab ẩn vẫn đếm), hết hạn thì trả slot và sang chế độ xem ===== */
/* ?idleMs / ?idleWarnMs chỉ đọc khi có ?test (để test rút ngắn) */
function idleParams(): [number, number] {
  const q = new URLSearchParams(location.search);
  if (!q.has('test')) return [M.idleMs, M.idleWarnMs];
  const n = (k: string, d: number) => { const v = Number(q.get(k)); return q.has(k) && v > 0 ? v : d; };
  return [n('idleMs', M.idleMs), n('idleWarnMs', M.idleWarnMs)];
}

function idleShow(text: string): void {
  const el = document.getElementById('exMpIdle');
  if (!el || text === idleShown) return;
  /* Lần đầu hiện thì đọc to một lần; các giây sau chỉ đổi chữ, không đọc lại */
  el.setAttribute('aria-live', idleShown === '' ? 'polite' : 'off');
  idleShown = text;
  el.textContent = text;
  el.hidden = text === '';
}

function idleTick(): void {
  if (!session || !idle || session.phase !== 'flying') return;
  const now = performance.now();
  const st = idle.tick(now);
  if (st === 'ok') idleShow('');
  else if (st === 'warn') idleShow(t('exMpIdle', { s: idle.remaining(now) }));
  else { idleShow(''); session.leave(); }   // leave → onChange → idleStop
}

function idleStart(): void {
  if (idleTimer || !session) return;   // đã chạy: không mở hai đồng hồ
  const [a, b] = idleParams();
  idle = new ExIdle(a, b); idle.reset(performance.now());
  idleShown = '';
  idleTimer = window.setInterval(idleTick, M.idleTickMs);
  beatTimer = window.setInterval(() => session?.heartbeat(), M.heartbeatMs);
}

function idleStop(): void {
  clearInterval(idleTimer); clearInterval(beatTimer);
  idleTimer = beatTimer = 0; idle = null;
  idleShow('');
}

/* Danh sách người chơi ở góc màn hình: đầu "Lái xe n/5 · Đi dạo n/5 · Bay n/5", rồi nhóm người lái (chấm thoi), người đi dạo (chấm vuông) và người bay (chấm tròn),
   mỗi người một dòng có chấm màu theo slot; dòng của mình đậm. Dùng textContent */
function renderRoster(): void {
  const box = document.getElementById('exMpRoster');
  if (!box) return;
  const flyers = session ? session.flyers : [], walkers = session ? session.walkers : [], drivers = session ? session.drivers : [];
  const head = t('drRosterAll', { d: drivers.length, w: walkers.length, f: flyers.length });
  const kind = session ? session.kind : 'fly', mine = session ? session.mySlot : -1;
  const key = drivers.map(f => f.slot + ':' + f.name).join('|') + '#' + walkers.map(f => f.slot + ':' + f.name).join('|') + '#' + flyers.map(f => f.slot + ':' + f.name).join('|') + '#' + kind + mine + '#' + head;
  if (key === rosterKey) return;
  rosterKey = key;
  box.hidden = !session || session.phase === 'solo';
  box.textContent = '';
  const h = document.createElement('div'); h.className = 'ex-mp-head'; h.textContent = head; box.appendChild(h);
  const group = (list: typeof flyers, k: 'fly' | 'walk' | 'drive') => {
    for (const f of list) {
      const row = document.createElement('div'); row.className = 'ex-mp-row' + (k === 'walk' ? ' walk' : k === 'drive' ? ' drive' : '') + (k === kind && f.slot === mine ? ' me' : '');
      const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
      const nm = document.createElement('span'); nm.textContent = f.name;
      row.append(dot, nm); box.appendChild(row);
    }
  };
  group(drivers, 'drive'); group(walkers, 'walk'); group(flyers, 'fly');
}

/* Người đi dạo hiện cho cả người bay: dựng nhóm nhân vật (lười) lần đầu phòng có người đi dạo; mô hình có xương nạp khi slot đầu tiên hiện */
function stEnsureAvatars(): void {
  const mesh = stAvatars.build();
  if (!mesh.parent) scene.add(mesh);
}

/* Xe người lái hiện cho cả người bay và người đi dạo: gắn / gỡ nhóm xe theo số xe (không có xe thì không ở trong cảnh) */
exDrivers.onCars = (n: number): void => {
  const g = drCars.group;
  if (n > 0) { if (!g.parent) scene.add(g); } else if (g.parent) g.removeFromParent();
};

export const exMulti = {
  /* Địa chỉ máy chủ: có ?test thì ?multi= nếu có, không có thì rỗng (không mở mạng); không có ?test thì luôn là địa chỉ cấu hình (người ngoài không đổi được máy chủ qua URL) */
  url(): string {
    const q = new URLSearchParams(location.search);
    if (!q.has('test')) return M.url;
    return q.get('multi') ?? '';
  },
  get session(): MultiSession | null { return session; },
  onChange: (() => {}) as () => void,   // móc cho giao diện sảnh (Task 6) và test

  /* Mở phiên loại kind ('fly' giành chỗ bay, 'walk' giành chỗ đi dạo, 'drive' giành chỗ lái xe); onReady gọi một lần khi có thông tin đầu tiên (sảnh hoặc ngoại tuyến). Trả false nếu không có địa chỉ */
  begin(onReady: () => void, kind: Kind = 'fly'): boolean {
    const url = exMulti.url();
    if (!url || session) return false;
    const s = session = new MultiSession(() => exConnect(url, M.connectTimeoutMs), undefined, kind);
    let ready = false;
    s.onPos = f => exRemotes.onPos(f, performance.now());
    s.onWalkPos = w => stAvatars.onPos(w, performance.now());
    s.peersDrive = d => exDrivers.onPos(d, performance.now());
    s.onChange = () => {
      exRemotes.sync(s.flyers, s.kind === 'fly' ? s.mySlot : -1);   // slot đi dạo và slot bay là hai nhóm: số slot của mình chỉ loại trừ trong nhóm của mình
      if (s.walkers.length || stAvatars.mesh) { stEnsureAvatars(); stAvatars.sync(s.walkers, s.kind === 'walk' ? s.mySlot : -1); }
      exDrivers.sync(s.drivers, s.kind === 'drive' ? s.mySlot : -1);
      if (s.phase === 'solo') exLabelsClear();
      renderRoster();
      if (s.phase === 'flying') idleStart(); else idleStop();
      exMulti.onChange();
      if (!ready) { ready = true; onReady(); }
    };
    s.open();
    return true;
  },

  /* Đóng phiên (Quay lại / Esc ở sảnh, hoặc chọn Bay một mình khi có máy chủ): đóng WebSocket, ẩn dù người khác, nhãn, danh sách; begin() mở lại được */
  end(): void {
    if (!session) return;
    session.dispose(); session = null;
    exMulti.onChange = () => {};
    idleStop(); exRemotes.clear(); stAvatars.clear(); exDrivers.clear(); exLabelsClear();
    rosterKey = ''; renderRoster();
  },

  /* Mỗi khung (bay, đi dạo, lái xe hoặc xem): dù người khác, người đi dạo khác, xe người khác, nhãn; đang bay thì gửi vị trí sendHz lần/s (state = null: không gửi) */
  update(dt: number, nowMs: number, state: GliderState | null): void {
    if (!session) return;
    exRemotes.update(nowMs);
    if (stAvatars.mesh) stAvatars.update(nowMs);   // người đi dạo khác, kể cả khi mình bay dù
    exDrivers.update(nowMs, dt);   // xe người khác, kể cả khi mình bay dù hoặc đi dạo
    exLabelsUpdate(camera, exRemotes, nowMs, stAvatars, exDrivers);
    if (state && session.kind === 'fly' && session.phase === 'flying' && nowMs - sentAt >= 1000 / M.sendHz) {
      sentAt = nowMs;
      const p = state.pos, r = (v: number) => Math.round(v * 10) / 10, a = (v: number) => Math.round(v * 1000) / 1000;
      session.sendPos(r(p.x), r(p.y), r(p.z), a(state.yaw), a(state.bank), Math.round(nowMs));
    }
  },

  /* Mỗi khung khi đi dạo có chỗ: gửi vị trí + dáng sendHz lần/s (s = null: không gửi) */
  updateWalk(nowMs: number, s: StState | null): void {
    if (!session || !s || session.kind !== 'walk' || session.phase !== 'flying' || nowMs - sentAt < 1000 / M.sendHz) return;
    sentAt = nowMs;
    const r = (v: number) => Math.round(v * 100) / 100, a = (v: number) => Math.round(v * 1000) / 1000;
    session.sendWalk(r(s.x), r(s.y), r(s.z), a(s.yaw), s.pose, Math.round(nowMs));
  },

  /* Mỗi khung khi lái xe có chỗ: gửi vị trí + vận tốc + góc lái sendHz lần/s (s = null: không gửi). Cả lúc đang sơ tán khỏi nhịp quay Cầu sông Hàn */
  updateDrive(nowMs: number, s: DrState | null): void {
    if (!session || !s || session.kind !== 'drive' || session.phase !== 'flying' || nowMs - sentAt < 1000 / M.sendHz) return;
    sentAt = nowMs;
    const r = (v: number) => Math.round(v * 100) / 100, a = (v: number) => Math.round(v * 1000) / 1000;
    session.sendDrive({ x: r(s.x), y: r(s.y), z: r(s.z), yaw: a(s.yaw), v: r(s.v), st: a(s.steer), ts: Math.round(nowMs) });
  },

  /* Người chơi vừa bấm phím điều khiển: đếm lại thời gian rời máy */
  activity(): void {
    if (!idle) return;
    idle.activity(performance.now());
    idleShow('');
  },

  /* Trạng thái dù đang xem (khi hết chỗ, Task 6); null nếu không xem ai */
  watchState(): GliderState | null {
    return session && session.kind === 'fly' && session.phase === 'watching' ? exRemotes.slotState(session.watched) : null;
  },

  /* Trạng thái người đi dạo đang xem (hết chỗ đi dạo); null nếu không xem ai */
  watchWalker(): { x: number; y: number; z: number; yaw: number; pose: number } | null {
    return session && session.kind === 'walk' && session.phase === 'watching' && session.watched >= 0 ? stAvatars.slotState(session.watched) : null;
  },

  /* Trạng thái xe đang xem (hết chỗ lái); null nếu không xem ai hoặc xe chưa có mẫu */
  watchDriver(): { x: number; y: number; z: number; yaw: number; v: number } | null {
    return session && session.kind === 'drive' && session.phase === 'watching' && session.watched >= 0 ? exDrivers.slotState(session.watched) : null;
  }
};

onLang(() => { rosterKey = ''; renderRoster(); });
/* ============================ Đi dạo: điều phối chế độ (một mình hoặc nhiều người, máy tính) ============================
   Nối bản đồ va chạm (map / mapData / sceneData), chuyển động (motion), nhân vật (avatars), camera sau lưng (camera) với vòng animate, phím, chuột.
   `?explore=stroll` vào thẳng, đi một mình (explore/index.ts gọi start). Esc và nút Thoát dùng explore.exit() (tải lại trang, D-020).
   - Bản đồ dựng lần đầu vào chế độ: dữ liệu tĩnh + nhà / chân đế thu từ cảnh đã dựng (chỉ đọc, sau mọi rand()).
   - Nhịp quay Cầu sông Hàn đóng với người đi dạo khi cầu rời trạng thái CLOSED (spec §3 mục 13); không tự quay, không tăng tốc quay.
   - Ban đêm Cầu Rồng tự phun như khi bay dù (exNightStep, không đụng cầu quay).
   - Không có nhảy (D-030): Space chỉ bị chặn hành vi mặc định (không cuộn trang, không bấm nút đang focus), không vào keys.
   - Phím chỉ ghi khi đang đi dạo, bỏ qua ô nhập và tổ hợp Ctrl / Meta / Alt; blur, ẩn tab, focus vào ô nhập thì xóa hết phím (Review Focus 3).
   - Nhiều người (exMulti, phiên kind 'walk'): xuất phát theo slot đi dạo, gửi vị trí + dáng; hết chỗ thì chế độ xem (startWatching) đặt camera sau lưng người được xem.
     Đổi phiên như dù lượn: bị thu chỗ → xem; mất kết nối khi đang đi → đi tiếp một mình + thông báo; mất kết nối khi xem → thoát, màn chọn báo mất kết nối.
   - Rời máy: phím điều khiển, kéo chuột và chạm cảm ứng gọi exMulti.activity().
   - Cảm ứng (touch.ts, #stHud): cần gạt ghi đè phím khi đang được giữ; vuốt nửa phải xoay camera; 📷 và phím P gọi stPhoto (photo.ts: chụp canvas sau lệnh vẽ chính).
   Mỗi khung không cấp phát (D-018). */
import type * as THREE from 'three';
import { scene, camera, controls, canvas, renderer } from '../../core/renderer';
import { composer } from '../../core/postprocessing';
import { cam, keys } from '../../views/state';
import { CONFIG } from '../../config';
import { stSetGate, type StMap } from './map';
import { ST_GATE_SWING, stBuildStaticMap } from './mapData';
import { stCreate, stStep, stPhotoPose, type StState, type StInput } from './motion';
import { stPhotoRequest, stPhotoAfterRender, stPhotoLast } from './photo';
import { stAvatars } from './avatars';
import { stRigSetWarm } from './rig';
import { stCollectRuntime } from './sceneData';
import { stCamPlace, stCamDrag, type StCam } from './camera';
import { stInputFromKeys, stKeyName } from './keys';
import { stTouchBind } from './touch';
import { exNightStep } from '../nightShows';
import { exMulti } from '../multi';
import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from '../multi/watch';
import type { SwingController } from '../../bridges/song-han/SwingController';

const ST_SOLO_SLOT = -1;     // stCreate / stSpawn: đi một mình đứng giữa các điểm xuất phát
const ST_SOLO_AVATAR = 0;    // slot nhân vật khi đi một mình (avatars.ts; mình luôn là mô hình 0)

/* Làm nóng shader nhân vật có xương (D-018), như core/prewarm.ts: hai biến thể (vẽ thẳng ra canvas ban ngày, vào render target của composer ban đêm),
   đèn / sương / bóng lấy từ cảnh chính (targetScene = scene), camera chính (đèn lọc theo lớp của nó). Cảnh nguồn không thêm vào scene */
stRigSetWarm(async (o: THREE.Object3D) => {
  const rt = renderer.getRenderTarget();
  renderer.setRenderTarget(null);
  const a = renderer.compileAsync(o, camera, scene);
  renderer.setRenderTarget(rt);
  await a;
  renderer.setRenderTarget(composer.readBuffer);
  const b = renderer.compileAsync(o, camera, scene);
  renderer.setRenderTarget(rt);
  await b;
});

let map: StMap | null = null;
let state: StState | null = null;
let ctrl: SwingController | null = null;
let exit: () => void = () => {};   // thoát chung (explore.exit), do setupStroll nhận
let selfSlot = ST_SOLO_AVATAR;   // instance nhân vật của mình: slot đi dạo khi có chỗ, giữ nguyên khi mất kết nối (màu áo không đổi)
let watching = false;        // đang xem người khác đi dạo (hết chỗ hoặc vừa nhường chỗ): không có nhân vật của mình, không đọc phím
let touch: ReturnType<typeof stTouchBind> | null = null;   // điều khiển cảm ứng (setupStroll dựng)
let chased = false;          // camera đã bám người được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
const camS: StCam = { yaw: 0, pitch: CONFIG.stroll.cam.pitch };
const _inp: StInput = { mx: 0, mz: 0, run: false, camYaw: 0 };   // đầu vào tái dùng mỗi khung

const active = () => cam.mode === 'stroll' && state !== null;
const inMode = () => active() || watching;   // Esc và giao diện đi dạo áp cho cả chế độ xem
/* Chụp ảnh (nút 📷, phím P): giơ tay (dáng 4, tới người khác qua gói vị trí kế tiếp), chớp màn hình, xếp yêu cầu chụp cho sau lệnh vẽ */
let flashTimer = 0;
function stPhoto(): void {
  if (!active()) return;
  stPhotoPose(state!);
  const f = document.getElementById('stFlash');
  if (f) { f.classList.add('on'); clearTimeout(flashTimer); flashTimer = window.setTimeout(() => f.classList.remove('on'), CONFIG.stroll.flashMs); }
  stPhotoRequest();
}
const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');

/* Một bước: cổng nhịp quay, chuyển động, nhân vật, camera, hiệu ứng đêm, người chơi khác */
function advance(dt: number, inp: StInput): void {
  if (ctrl) stSetGate(map!, ST_GATE_SWING, ctrl.state !== 'CLOSED');
  stStep(state!, inp, map!, dt);
  stAvatars.setSelf(selfSlot, state, dt);   // dt cho mixer của nhân vật có xương
  stCamPlace(camera, controls.target, state!, camS, map!, dt);
  exNightStep(dt, false);
  const now = performance.now();
  exMulti.update(dt, now, null);   // người khác (đi dạo + bay), nhãn tên; không làm gì khi đi một mình
  exMulti.updateWalk(now, state);  // gửi vị trí + dáng khi đang giữ chỗ
}

/* Mỗi khung khi xem: người khác, nhãn, danh sách; camera sau lưng người được xem (hướng camera = hướng mặt họ). Không có ai thì camera giữ nguyên */
function watchStep(dt: number): void {
  if (ctrl) stSetGate(map!, ST_GATE_SWING, ctrl.state !== 'CLOSED');
  exMulti.update(dt, performance.now(), null);
  const w = exMulti.watchWalker();
  if (w) { camS.yaw = w.yaw; stCamPlace(camera, controls.target, w, camS, map!, dt, !chased); chased = true; }
  exNightStep(dt, false);
}

/* Đổi phiên khi đang xem hoặc đang đi: vào đi, mất kết nối, bị thu hồi chỗ (như onMultiChange của dù lượn) */
function stOnMultiChange(): void {
  const s = exMulti.session; if (!s) return;
  if (watching) {
    if (s.phase === 'flying') { stroll.start(); return; }   // chấp nhận lời mời: xuất phát như vào đi thường
    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lostWalk'); } catch { /* bộ nhớ bị chặn */ } exit(); return; }   // màn chọn đọc cờ này và hiện stLostChooser (nhắc Đi dạo, không phải Dù lượn)
    exWatchRender();
  } else if (active()) {
    if (s.phase === 'watching') { state = null; stAvatars.setSelf(selfSlot, null); stroll.startWatching(true); return; }   // chỗ bị thu hồi (rời máy): sang xem, camera giữ nguyên
    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'stLost');   // vẫn đi, người khác đã biến mất
  }
}

