1	/* ===== Worker + Durable Object phòng bầu trời chung: bọc SkyRoom, WebSocket hibernation ===== */
2	import { multiParams as P } from '../../../src/explore/multi/params';
3	import { SkyRoom } from './room';
4	import type { Out } from './room';
5	
6	interface Env { SKY: DurableObjectNamespace; ALLOWED_ORIGINS: string }
7	interface Att { id: string; slot: number; name: string; seen?: number; kind?: 'walk' | 'drive' }   // seen: giờ có tin cuối của người giữ slot, ghi thưa (mỗi heartbeatMs) để sống sót qua hibernation; kind: 'walk' = slot nằm ở nhóm đi dạo, 'drive' = nhóm lái xe, không có = nhóm bay
8	
9	// So khớp scheme + hostname, bỏ cổng
10	function originKey(o: string): string | null {
11	  try { const u = new URL(o); return u.protocol + '//' + u.hostname; } catch { return null; }
12	}
13	
14	// Mục cho phép có '*' (vd. bản xem trước PR của Netlify): '*' chỉ khớp một đoạn chữ thường/số, không có '.' hay '-'
15	function originAllowed(key: string, pattern: string): boolean {
16	  const p = originKey(pattern.replace(/\*/g, 'x'));
17	  if (!p) return false;
18	  if (!pattern.includes('*')) return p === key;
19	  const re = new RegExp('^' + pattern.trim().split('*').map(s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('[a-z0-9]+') + '$');
20	  return re.test(key);
21	}
22	
23	export default {
24	  async fetch(req: Request, env: Env): Promise<Response> {
25	    const url = new URL(req.url);
26	    if (url.pathname !== '/sky') return new Response('Not found', { status: 404 });
27	    if (req.headers.get('Upgrade') !== 'websocket') return new Response('Expected WebSocket', { status: 426 });
28	    const key = originKey(req.headers.get('Origin') || '');
29	    if (!key || !env.ALLOWED_ORIGINS.split(',').some(s => originAllowed(key, s.trim()))) return new Response('Forbidden', { status: 403 });
30	    return env.SKY.get(env.SKY.idFromName('sky')).fetch(req);
31	  }
32	};
33	
34	export class SkyObject implements DurableObject {
35	  private room = new SkyRoom();
36	  private names = new Map<number, string>();
37	  private walkNames = new Map<number, string>();   // tên người đi dạo theo slot, lấy từ walkers của lobby
38	  private driveNames = new Map<number, string>();  // tên người lái theo slot, lấy từ drivers của lobby
39	  private armed: boolean | null = null;   // đã đặt alarm chưa; null = chưa biết (vừa dựng hoặc vừa thức dậy): hỏi storage một lần
40	
41	  constructor(private state: DurableObjectState, _env: Env) {
42	    // Đánh thức sau hibernation: dựng lại phòng từ attachment của từng socket
43	    const now = Date.now();
44	    const list: Att[] = [];
45	    for (const ws of this.state.getWebSockets()) {
46	      const a = ws.deserializeAttachment() as Att | null;
47	      if (!a) continue;
48	      this.room.connect(a.id, now);
49	      if (a.slot >= 0) list.push(a);
50	    }
51	    this.room.restore(list, now);
52	  }
53	
54	  async fetch(_req: Request): Promise<Response> {
55	    const pair = new WebSocketPair();
56	    const [client, server] = [pair[0], pair[1]];
57	    const id = crypto.randomUUID();
58	    this.state.acceptWebSocket(server);
59	    server.serializeAttachment({ id, slot: -1, name: '' } as Att);
60	    const outs = this.room.connect(id, Date.now());
61	    if (outs === null) { server.close(1013, 'full'); return new Response(null, { status: 503 }); }
62	    this.dispatch(outs);
63	    return new Response(null, { status: 101, webSocket: client });
64	  }
65	
66	  async webSocketMessage(ws: WebSocket, data: string | ArrayBuffer): Promise<void> {
67	    const a = ws.deserializeAttachment() as Att | null;
68	    if (!a || typeof data !== 'string') return;
69	    this.dispatch(this.room.message(a.id, data, Date.now()));
70	    await this.armAlarm();
71	  }
72	
73	  async webSocketClose(ws: WebSocket): Promise<void> { this.drop(ws); }
74	  async webSocketError(ws: WebSocket): Promise<void> { this.drop(ws); }
75	
76	  async alarm(): Promise<void> {
77	    this.armed = false;   // alarm đã chạy thì không còn alarm nào chờ
78	    this.dispatch(this.room.sweep(Date.now()));
79	    await this.armAlarm();
80	  }
81	
82	  private drop(ws: WebSocket): void {
83	    const a = ws.deserializeAttachment() as Att | null;
84	    if (a) this.dispatch(this.room.disconnect(a.id));
85	  }
86	
87	  // Gửi tin ra socket rồi ghi lại slot/tên/seen mới vào attachment (để sống sót qua hibernation); seen chỉ ghi khi cũ hơn heartbeatMs
88	  private dispatch(outs: Out[]): void {
89	    const socks = this.state.getWebSockets();
90	    for (const o of outs) {
91	      const text = JSON.stringify(o.msg);
92	      for (const ws of socks) {
93	        const a = ws.deserializeAttachment() as Att | null;
94	        if (!a || (o.to !== 'all' && o.to !== a.id)) continue;
95	        try { ws.send(text); } catch { /* socket đã đóng */ }
96	      }
97	      if (o.msg.t === 'lobby') {
98	        this.names = new Map(o.msg.flyers.map(f => [f.slot, f.name]));
99	        this.walkNames = new Map((o.msg.walkers ?? []).map(f => [f.slot, f.name]));
100	        this.driveNames = new Map((o.msg.drivers ?? []).map(f => [f.slot, f.name]));
101	      }
102	    }
103	    for (const ws of socks) {
104	      const a = ws.deserializeAttachment() as Att | null;
105	      if (!a) continue;
106	      const kind = this.room.kindOf(a.id);
107	      const walk = kind === 'walk', drive = kind === 'drive';
108	      const slot = walk ? this.room.walkSlotOf(a.id) : drive ? this.room.driveSlotOf(a.id) : this.room.slotOf(a.id);
109	      const name = slot >= 0 ? ((walk ? this.walkNames : drive ? this.driveNames : this.names).get(slot) ?? a.name) : '';
110	      const seen = this.room.seenOf(a.id);
111	      const stale = slot >= 0 && !(seen - (a.seen ?? -Infinity) < P.heartbeatMs);
112	      const k = walk ? 'walk' : drive ? 'drive' : undefined;   // loại ghi trong attachment; người bay không ghi (attachment như bản cũ)
113	      if (slot !== a.slot || name !== a.name || a.kind !== k || stale) {
114	        const next: Att = slot < 0 ? { id: a.id, slot, name } : k ? { id: a.id, slot, name, seen, kind: k } : { id: a.id, slot, name, seen };
115	        ws.serializeAttachment(next);
116	      }
117	    }
118	  }
119	
120	  private async armAlarm(): Promise<void> {
121	    if (!this.room.hasFlyers() || this.armed) return;
122	    if (this.armed === null && (await this.state.storage.getAlarm()) !== null) { this.armed = true; return; }
123	    this.armed = true;
124	    try { await this.state.storage.setAlarm(Date.now() + P.sweepMs); } catch (e) { this.armed = false; throw e; }
125	  }
126	}
