  const walkTo = async (pg, name) => {   // sảnh đi dạo → nhập tên → Đi dạo ngay → đang đi với slot
    await pg.waitForFunction(() => /Còn \d trên 5 chỗ đi dạo/.test(document.getElementById('exMpSeats')?.innerText || ''), null, { timeout: 30000 }).catch(() => {});
