  const dropW = (b) => { b.close(); const i = wbots.indexOf(b); if (i >= 0) wbots.splice(i, 1); };

  // 6d — bot giả khách cũ (join không kind, chỉ đọc flyers / f) cùng phòng với 2 bot đi dạo (Review Focus 4)
