    ows2.onmessage = (e) => { const m = JSON.parse(e.data); oldMsgs.push(m); if (m.t === 'joined' && !oldTimer) oldTimer = setInterval(() => ows2.send(JSON.stringify({ t: 'pos', x: 300, y: 120, z: 0, yaw: 0, bank: 0 })), 200); };
